"use strict";
const byId=id=>document.getElementById(id);
const courseById=id=>ALL_COURSES.find(c=>c.id===id);
const targetById=id=>CAMPUSES.find(t=>t.id===id);
const dialog=byId("detail-dialog");
let toastTimer,explorerQuery="",explorerCategory="All";
const link=(url,label)=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(label)+' ↗</a>';
function notify(message){byId("toast").textContent=message;byId("toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId("toast").classList.remove("visible"),3000)}
function relationship(c,t){const miramarAgreement=c.schoolId==="miramar"?assistAgreementFor(t.id):null;if(miramarAgreement){const a=miramarAgreement,items=agreementItems(a).filter(i=>i.courseIds.includes(c.id)&&!i.alternateListing);if(items.length)return{kind:"verified",label:items.map(i=>(i.labels&&i.labels[c.id])||i.receivingCode).join(" · "),note:c.code+" is a Miramar sending course for "+items.map(i=>i.receivingCode+" ("+i.receivingTitle+")").join(", ")+" in the "+a.receiving+" "+a.program+" "+a.year+" agreement.",program:a.program,year:a.year,published:a.published,source:a.source,programNote:items.map(i=>(i.notesByCourse&&i.notesByCourse[c.id])||"").filter(Boolean).join(" ")};return{kind:"unknown",label:"Not listed in agreement",note:c.code+" is not a sending course in the "+a.receiving+" "+a.program+" "+a.year+" agreement.",program:a.program,year:a.year,published:a.published,source:a.source,reviewed:true}}if(c.schoolId==="miramar")return{kind:"unknown",label:"Major match not verified",note:"No "+t.name+" "+escapeHTML(PLAN.major)+" agreement from Miramar is in this demo."};const agreement=isCS()?ASSIST_AGREEMENTS[t.id]:null;if(agreement){const match=agreement.matches[c.id];if(match)return{kind:"verified",label:match.receiving,note:c.code+" articulates to "+match.receiving+" ("+match.title+") for "+agreement.program+" in the "+agreement.year+" ASSIST agreement.",program:agreement.program,year:agreement.year,published:agreement.published,source:agreement.source,programNote:match.programNote||""};if(agreement.reviewed.includes(c.id))return{kind:"unknown",label:"Not listed in reviewed agreement",note:c.code+" was not found as an articulated sending course in the reviewed "+agreement.program+" "+agreement.year+" agreement.",program:agreement.program,year:agreement.year,published:agreement.published,source:agreement.source,reviewed:true};}if(t.id==="ucsd"&&c.verified)return{kind:"verified",label:c.verified,note:"Published UCSD department equivalency; individual year/grade applicability still needs review.",source:SOURCES.ucsdMath};if(isCS()&&["ucsd","sdsu","csusm"].includes(t.id)&&c.targets.includes(t.id))return{kind:"demo",label:"Illustrative CS match",note:"Sample mapping only—not an official articulation."};return{kind:"unknown",label:"Major match not verified",note:"Catalog lists general "+t.system+" transferability; this is not a confirmed "+escapeHTML(PLAN.major)+" requirement match."}}
function applicable(c){return chosenCampuses().filter(t=>relationship(c,t).kind!=="unknown")}
function evidenceByKind(c){const r={verified:[],demo:[]};for(const t of chosenCampuses()){const k=relationship(c,t).kind;if(r[k])r[k].push(t.name)}return r}
function getStats(){const r={completed:0,registered:0,planning:0,completedUnits:0,registeredUnits:0,planningUnits:0,contributions:0,verifiedContributions:0,demoContributions:0,helped:0};for(const c of selectedRecords()){const s=statusOf(c.id);r[s]++;r[s+"Units"]+=c.units;if(s==="planning"){const e=evidenceByKind(c);r.verifiedContributions+=e.verified.length;r.demoContributions+=e.demo.length;r.contributions+=e.verified.length+e.demo.length}}r.helped=chosenCampuses().filter(t=>selectedRecords().some(c=>statusOf(c.id)==="planning"&&relationship(c,t).kind!=="unknown")).length;return r}
function readState(){return{view:PLAN.view,college:PLAN.college,major:PLAN.major,targetIds:[...PLAN.targetIds],statuses:{...PLAN.statuses},...getStats(),mode:"Demo; user-entered status, static ASSIST Computer Science agreement snapshots (Miramar to UC Berkeley, UCLA and Cal Poly San Luis Obispo; Mesa to UC Berkeley, UCLA and Cal Poly Pomona), two UCSD department relationships, limited illustrative matches elsewhere"}}
function showDialog(title,html){byId("dialog-title").textContent=title;byId("dialog-body").innerHTML=html;if(!dialog.open)dialog.showModal()}
function showSources(){showDialog("Sources, coverage & privacy",'<div class="evidence-banner"><span class="evidence-icon">✓</span><div><strong>Official facts and sample logic stay separate.</strong><p>Source snapshot · September 14, 2026</p></div></div><div class="source-block"><h3>Source-driven Miramar pathways</h3><p>Choosing Miramar and Computer Science opens frozen copies of complete 2025–26 agreements for UC Berkeley, UCLA and Cal Poly San Luis Obispo: every section and group, AND/OR and unit rules, no-articulation items and agreement notes. They were read on ASSIST and entered by hand for this demo; approved ASSIST API access will replace them.</p>'+Object.values(MIRAMAR_CS_AGREEMENTS).map(a=>'<p>'+link(a.source,"Miramar → "+a.receiving+" "+a.program+" · "+a.year)+'</p>').join("")+'<p>This is static POC data, not live scraping. Approved API access should replace snapshots with a maintained ingestion process.</p>'+link(SOURCES.assistApiDocs,"ASSIST agreement API documentation")+'</div><div class="source-block"><h3>Options at other San Diego-area colleges</h3><p>When Miramar has no articulated course for a Berkeley requirement, Step 4 shows what the same '+NEARBY_UCB_CS.year+' UC Berkeley '+NEARBY_UCB_CS.program+' agreement lists at nearby colleges. Viewed on ASSIST '+NEARBY_UCB_CS.retrieved+'. These options are informational: Miramar acceptance, prerequisites and seats are not verified.</p>'+NEARBY_UCB_CS.checked.map(c=>'<p>'+link(c.source,c.name+' → UC Berkeley · '+NEARBY_UCB_CS.year)+'</p>').join("")+'</div><div class="source-block"><h3>Additional Mesa comparison snapshots</h3><p>The fallback demo includes seven Mesa catalog-backed courses plus reviewed Computer Science agreements for Berkeley, UCLA and Cal Poly Pomona. “Not listed” is not an admission decision or a statement that a course cannot transfer.</p>'+Object.values(ASSIST_AGREEMENTS).map(a=>'<p>'+link(a.source,a.program+' · '+a.year)+'</p>').join("")+link(SOURCES.catalog,"Mesa 2026–27 catalog")+'</div><div class="source-block"><h3>Other demo evidence</h3><p>Mesa MATH 150 → UCSD MATH 20A and MATH 151 → UCSD MATH 20B come from UCSD’s department table. Other unsupported campus-major relationships remain explicitly illustrative or unknown.</p>'+link(SOURCES.ucsdMath,"UCSD department table")+'<p>'+link(SOURCES.sdsuPathway,"SDSU–SDCCD pathway")+'</p></div><div class="source-block"><h3>Your entries are not verified academic records</h3><p>Completed, registered and planning are self-reported statuses. No grades, transcripts, prerequisites, GE, GPA, unit eligibility, deadlines, live sections or admission conditions are validated.</p><p>Your choices stay only in this tab’s memory. Refreshing starts over. Copying or downloading a summary includes the information shown in it.</p></div><p class="directory-links">'+link(SOURCES.classSearch,"Official SDCCD class search")+link(SOURCES.assist,"Open ASSIST")+link(SOURCES.assistTerms,"ASSIST reuse terms")+'</p>')}
function showCourse(id){const c=courseById(id);const evidence=chosenCampuses().map(t=>({t,m:relationship(c,t)})),miramar=c.schoolId==="miramar";showDialog(c.code+" · Course evidence",'<span class="source-pill verified school-inline">'+schoolBadge(c.schoolId||"mesa")+c.college+' · '+c.catalogYear+'</span><h3 class="detail-title">'+c.title+'</h3><div class="detail-facts"><span><strong>'+c.units+'</strong> units</span><span>'+(miramar?"Agreement sending course":"UC/CSU transferable in catalog")+'</span><span>'+STATUS_LABELS[statusOf(id)]+' · self-reported</span></div><div class="source-block"><h3>Your selected campuses</h3><div class="evidence-rows">'+evidence.map(({t,m})=>'<div><strong class="school-inline">'+schoolBadge(t.id)+t.name+'</strong><span><span class="match-pill '+m.kind+'">'+m.label+'</span><small>'+(m.year?m.program+' · '+m.year:m.note)+'</small></span></div>').join("")+'</div></div><div class="source-block"><h3>Official course information</h3><p>'+link(c.source,miramar?"Open ASSIST agreement":"Mesa course page")+(miramar?'':' · '+link(SOURCES.catalog,"Catalog, printed page "+c.page))+'</p>'+evidence.filter(x=>x.m.source).map(({t,m})=>'<p><strong>'+t.name+':</strong> '+m.note+(m.programNote?' '+m.programNote:'')+' '+link(m.source,"View source")+'</p>').join("")+(evidence.some(x=>x.m.source)?'':'<p>No campus-major equivalency is verified for this course in the demo.</p>')+'</div><p class="scope-note">General transferability does not prove major applicability. Check the applicable agreement year, prerequisites, grades, course availability and enrollment eligibility with official sources.</p>'+link(SOURCES.classSearch,"Check actual sections"))}
function showTarget(id){const t=targetById(id);const records=selectedRecords();showDialog(t.name+" · "+PLAN.major,'<div class="school-heading">'+schoolBadge(t.id)+'<strong>'+t.name+'</strong></div><span class="source-pill">'+t.system+' · Selected destination</span><p>The following uses your course statuses. It is an applicability preview, not a complete eligibility audit.</p><div class="target-detail-list">'+(records.length?records.map(c=>{const m=relationship(c,t);return'<div><div><strong>'+c.code+'</strong><small>'+STATUS_LABELS[statusOf(c.id)]+' · '+c.college.replace("San Diego ","")+' · '+c.units+' units</small></div><span class="match-pill '+m.kind+'">'+m.label+'</span></div>'}).join(""):'<p>No coursework added yet. Add courses to begin this comparison.</p>')+'</div><div class="source-block"><h3>What to verify next</h3><p>Check whether '+escapeHTML(PLAN.major)+' is offered at this campus and use the applicable campus-major/year agreement. Unknown matches do not mean the course will not transfer.</p>'+link(SOURCES.assist,"Open ASSIST")+'<p>'+link(t.system==="UC"?"https://www.universityofcalifornia.edu/about-uc/campuses-locations":"https://www.calstate.edu/attend/campuses","Find official campus information")+'</p></div><p class="scope-note">Source-linked = published course relationship. Illustrative = demo assumption. Not verified = major-specific evidence unavailable. Registered/planned work is not completed.</p>')}
function summary(){const s=getStats(),agreement=activeAssistAgreement();return "TRANSFER COPILOT — DEMO PLAN\nHome college: "+collegeName()+"\nIntended major: "+PLAN.major+"\nTargets: "+chosenCampuses().map(t=>t.name).join(", ")+"\n\n"+selectedRecords().map(c=>c.code+" — "+c.title+" | "+c.college+" | "+c.units+" units | "+STATUS_LABELS[statusOf(c.id)]).join("\n")+"\n\nCompleted: "+s.completedUnits+" units (self-reported)\nRegistered: "+s.registeredUnits+" units (not completed)\nPlanning: "+s.planningUnits+" units (not completed)\n\n"+chosenCampuses().map(t=>t.name+"\n"+selectedRecords().map(c=>c.code+": "+relationship(c,t).label).join("\n")).join("\n\n")+"\n\nLIMITATIONS: "+(agreement?("Static snapshots of the Miramar → "+activeAssistAgreements().map(a=>a.receiving).join(", ")+" Computer Science agreements. "):"The fallback course catalog sample is Mesa only. ")+"Registered/planned courses are not completed. No eligibility or admission guarantee, complete major audit, GE, GPA, prerequisite or live-seat verification. The website does not retain this profile. Sharing this summary includes the course selections above.\n\nOfficial agreement/source: "+(agreement?activeAssistAgreements().map(a=>a.source).join("\n"):SOURCES.catalog)+"\nOfficial class search: "+SOURCES.classSearch}
function showShare(parent=false){const s=getStats();showDialog(parent?"Family & counselor view":"Share your planning summary",'<div class="share-heading">'+schoolBadge(PLAN.college)+'<div><h3>Your transfer picture</h3><p>'+escapeHTML(collegeName())+' · '+escapeHTML(PLAN.major)+'</p></div></div><p>'+chosenCampuses().map(t=>t.name).join(" · ")+'</p><div class="summary-tiles"><div><strong>'+s.completedUnits+'</strong><span>completed units*</span></div><div><strong>'+s.registeredUnits+'</strong><span>registered units</span></div><div><strong>'+s.planningUnits+'</strong><span>planning units</span></div></div><div class="summary-courses">'+selectedRecords().map(c=>'<div><strong>'+c.code+'</strong><span>'+c.title+'</span><span>'+STATUS_LABELS[statusOf(c.id)]+'</span></div>').join("")+'</div><div class="summary-caution"><strong>Questions for a counselor</strong><p>Which courses apply to my intended major at each campus? What else is required? Are prerequisites cleared and which agreement year applies?</p></div><p class="scope-note">*Completed is self-reported, not a certified transfer-unit total. A copy or download includes your selections. The demo link alone does not share your answers; everyone starts fresh.</p><div class="dialog-actions"><button class="button navy" data-action="copy-summary">Copy summary</button><button class="button outline" data-action="download-summary">Download summary</button><button class="button subtle" data-action="copy-link">Copy demo link</button></div>')}
function showWhy(){const s=getStats();showDialog("Why this scenario?",'<span class="source-pill">Transparent demo logic · No live AI</span><h3 class="detail-title">'+s.planning+' planning courses · '+s.planningUnits+' units</h3><p>Scenario buttons only change Planning or Not added courses. Your completed and registered coursework is preserved.</p><p>The demo prioritizes source-linked or illustrative matches for the destinations you selected. A lighter scenario limits newly planned units. It does not certify prerequisites, choose an optimal real schedule, or predict admission.</p><div class="checklist">'+selectedRecords().filter(c=>statusOf(c.id)==="planning").map(c=>'<div><span class="check-status">↗</span><span><strong>'+c.code+'</strong><br><small>'+applicable(c).map(t=>t.name).join(" · ")+'</small></span><strong>'+c.units+' units</strong></div>').join("")+'</div><div class="source-block"><h3>Destination matches — demo measure</h3><p>'+s.verifiedContributions+' source-linked and '+s.demoContributions+' illustrative course–destination matches across '+s.planningUnits+' planned units, counted separately. Not-verified matches are excluded, not treated as academic failures. No universal score or completion percentage is produced.</p></div><button class="button outline" data-open="sources">Inspect the evidence</button>')}
function setCourseStatus(id,status){if(!courseById(id)||!Object.hasOwn(STATUS_LABELS,status))throw new Error("Invalid course status");PLAN.statuses[id]=status;PLAN.scenario="custom";render();return readState()}
function setScenario(name){if(!["balanced","lighter","original"].includes(name))throw new Error("Unknown scenario");if(PLAN.view!=="dashboard")throw new Error("Complete the setup first");if(name==="original"){PLAN.statuses={...PLAN.baseline};PLAN.scenario="original";render();return readState()}const courses=activeCourses(),candidates=courses.filter(c=>!["completed","registered"].includes(statusOf(c.id))&&applicable(c).length>0);if(!candidates.length){notify("No supported scenario matches for these choices. Add planning courses manually.");return readState()}const preferred=name==="lighter"?["math151","cisc246","math150","cisc190","cisc187","phys195","phys196"]:["math151","cisc187","cisc246","math150","cisc190","phys195","phys196"],order=[...preferred,...courses.map(c=>c.id).filter(id=>!preferred.includes(id))];let units=0;for(const c of courses)if(statusOf(c.id)==="planning")PLAN.statuses[c.id]="none";for(const id of order){const c=candidates.find(c=>c.id===id);if(c&&units+c.units<=(name==="lighter"?8:12)){PLAN.statuses[c.id]="planning";units+=c.units}}PLAN.scenario=name;render();return readState()}
// Transfer Efficiency: share of a destination's required decisions that are completed. Registered and planned work is
// drawn in the ring but never counted. Only computed from a complete source-linked agreement; illustrative or unverified matches never become a percentage.
function requirementCoverage(t){const a=assistAgreementFor(t.id);if(!a)return null;const levels=agreementDecisionLevels(a),n=k=>levels.filter(l=>l===k).length;return{agreement:a,total:levels.length,completed:n("completed"),registered:n("registered"),planning:n("planning")}}
function coverageRingHTML(t){const c=requirementCoverage(t);if(!c||!c.total)return '<div class="coverage-card unevaluated"><strong>Transfer Efficiency not calculated</strong><p>No complete source-linked '+escapeHTML(PLAN.major)+' agreement from '+escapeHTML(collegeName())+' to '+t.name+' in this demo. Illustrative or unverified matches are never turned into a percentage.</p></div>';const notStarted=c.total-c.completed-c.registered-c.planning,pct=completedPercent(c),r=52,C=2*Math.PI*r,parts=[["completed","#528440",1],["registered","#2f6db5",.38],["planning","#bd8b38",.38]];let offset=0;const arcs=parts.map(([k,color,opacity])=>{const len=C*c[k]/c.total,arc=len?'<circle r="'+r+'" cx="66" cy="66" fill="none" stroke="'+color+'" stroke-opacity="'+opacity+'" stroke-width="14" stroke-dasharray="'+len.toFixed(2)+' '+(C-len).toFixed(2)+'" stroke-dashoffset="'+(-offset).toFixed(2)+'"/>':'';offset+=len;return arc}).join("");const label=pct+'% of '+t.name+' '+c.agreement.efficiencyLabel.toLowerCase()+' completed: '+c.completed+' completed; '+c.registered+' registered and '+c.planning+' planned, not counted; '+notStarted+' not started; out of '+c.total+' counted requirements';return '<div class="coverage-card"><div class="coverage-ring" role="img" aria-label="'+label+'"><svg viewBox="0 0 132 132" width="132" height="132" aria-hidden="true"><g transform="rotate(-90 66 66)"><circle r="'+r+'" cx="66" cy="66" fill="none" stroke="#e3e8ef" stroke-width="14"/>'+arcs+'</g></svg><div class="ring-center" aria-hidden="true"><strong>'+pct+'%</strong><span>completed</span></div></div><div class="coverage-detail"><span class="coverage-title">Transfer Efficiency</span><h3>'+t.name+' · '+c.agreement.efficiencyLabel+'</h3><p>'+c.total+' counted requirements from the '+c.agreement.year+' '+c.agreement.program+' agreement from '+escapeHTML(collegeName())+'.</p><ul class="coverage-legend"><li><i style="background:#528440"></i>Completed<strong>'+c.completed+' of '+c.total+'</strong></li><li class="not-counted"><i style="background:#2f6db561"></i>Registered · not counted<strong>'+c.registered+'</strong></li><li class="not-counted"><i style="background:#bd8b3861"></i>Planning · not counted<strong>'+c.planning+'</strong></li><li><i style="background:#e3e8ef"></i>Not started<strong>'+notStarted+'</strong></li></ul><p class="coverage-caption">Only completed courses count toward this percentage; registered and planned courses are shown lighter until you complete them. Major preparation only—not GE, GPA, the 7-course pattern or admission odds.</p></div></div>'}
function completedPercent(c){return Math.round(c.completed/c.total*100)}
// Next best move: among courses not yet completed (not added, planned or registered), prefer the one whose completion adds
// the most completed required decisions where a complete agreement exists (raising Transfer Efficiency), then source-linked, then illustrative matches elsewhere; ties keep course order.
function courseCandidates(){const campuses=chosenCampuses(),before=new Map(campuses.map(t=>[t.id,requirementCoverage(t)]));const scored=activeCourses().filter(c=>statusOf(c.id)!=="completed").map(c=>{const prev=PLAN.statuses[c.id];PLAN.statuses[c.id]="completed";const after=new Map(campuses.map(t=>[t.id,requirementCoverage(t)]));if(prev===undefined)delete PLAN.statuses[c.id];else PLAN.statuses[c.id]=prev;const gains=campuses.filter(t=>before.get(t.id)&&after.get(t.id)).map(t=>{const b=before.get(t.id),a=after.get(t.id);return{t,gain:a.completed-b.completed,from:completedPercent(b),to:completedPercent(a)}}).filter(g=>g.gain>0);const other=campuses.filter(t=>!before.get(t.id)).map(t=>({t,m:relationship(c,t)})).filter(x=>x.m.kind!=="unknown");return{c,gains,maps:[...gains.map(g=>({t:g.t,m:relationship(c,g.t)})),...other],gain:gains.reduce((n,g)=>n+g.gain,0),verified:other.filter(x=>x.m.kind==="verified").length,demo:other.filter(x=>x.m.kind==="demo").length}});scored.sort((x,y)=>y.gain-x.gain||y.verified-x.verified||y.demo-x.demo);return scored}
function nextMove(){return courseCandidates().find(x=>x.gain||x.verified||x.demo)||null}
function nextMoveHTML(){const n=nextMove();if(!n)return '<p class="next-empty">'+(chosenCampuses().some(t=>{const c=requirementCoverage(t);return c&&c.total&&c.completed===c.total})?"Every required course in the agreement is completed.":activeCourses().some(c=>statusOf(c.id)!=="completed")?"No course left to complete has a source-linked or illustrative match for your selected schools.":"Every course in this sample is completed.")+'</p>';const s=statusOf(n.c.id);return '<div class="next-course"><strong>'+n.c.code+'</strong><span>'+n.c.title+' · '+n.c.units+' units</span><span class="next-status '+s+'">'+(s==="none"?"Not in your plan yet":STATUS_LABELS[s]+" · not completed")+'</span></div><div class="next-maps">'+n.maps.map(({t,m})=>'<div class="next-map"><span class="next-arrow" aria-hidden="true">→</span>'+schoolBadge(t.id)+'<span><strong>'+m.label+'</strong><small>'+t.name+(m.kind==="demo"?' · Illustrative':'')+'</small></span></div>').join("")+'</div>'+n.gains.map(g=>'<p class="next-why">Completing it: Transfer Efficiency at '+g.t.name+' '+g.from+'% → '+g.to+'%</p>').join("")+(s==="none"?'<button class="button lime" data-explore-add="'+n.c.id+'">Add to planning <span aria-hidden="true">+</span></button>':'<button class="button lime" data-course-detail="'+n.c.id+'">View course details <span aria-hidden="true">↗</span></button>')}
const EVIDENCE_KIND_NAME={verified:"Source-linked",demo:"Illustrative",unknown:"Not verified"};
function destinationBoxesHTML(c){return '<div class="fit-destinations">'+chosenCampuses().map(t=>{const m=relationship(c,t),detail=m.year?(m.kind==="verified"?"ASSIST · ":"Reviewed · ")+m.program+" · "+m.year:m.kind==="verified"?"Course equivalency; major need unconfirmed":m.kind==="demo"?"Not an official articulation":t.system+" transferability listed; major unknown";return '<div class="fit-dest '+m.kind+'"><div class="fit-dest-head">'+schoolBadge(t.id)+'<span>'+t.name+'</span></div><span class="match-pill '+m.kind+'">'+EVIDENCE_KIND_NAME[m.kind]+'</span><strong class="fit-dest-course">'+m.label+'</strong><small>'+detail+'</small>'+(m.source?'<button class="evidence-link" data-course-detail="'+c.id+'">Evidence ↗</button>':'')+'</div>'}).join("")+'</div>'}
function courseMapRowHTML(c,leftHTML){return '<article class="fit-row" aria-label="'+c.code+' mapped to your destinations">'+leftHTML+'<div class="mapping-arrow"><span aria-hidden="true">→</span><small>maps to</small></div>'+destinationBoxesHTML(c)+'</article>'}
function collegeShort(c){return (c.college||"").replace(/^San Diego /,"").replace(/ College$/,"")}
function renderTargets(){byId("target-list").innerHTML=chosenCampuses().map(t=>{return'<article class="target-card"><button class="target-row" data-target="'+t.id+'" aria-label="View '+t.name+' applicability and Transfer Efficiency">'+schoolBadge(t.id)+'<span class="target-name"><strong>'+t.name+'</strong></span><span class="chevron">↗</span></button>'+coverageRingHTML(t)+'</article>'}).join("");document.querySelector(".pathways .tiny-tag").textContent=PLAN.targetIds.size+" targets";document.querySelector(".pathways .muted").innerHTML=escapeHTML(PLAN.major)+' · <button class="text-button" data-action="edit-targets">Edit destinations</button>'}
function neededCourseIds(){const list=activeAssistAgreements();if(!list.length)return null;const ids=new Set(),rankOf=id=>STATUS_RANK[statusOf(id)];list.forEach(a=>a.sections.filter(s=>s.counts).forEach(s=>s.groups.forEach(g=>{if(groupLevels(g).every(l=>l==="completed"))return;const items=g.items.filter(i=>!i.alternateListing),itemRank=i=>STATUS_RANK[itemLevel(i)];let open=items.filter(i=>itemRank(i)<3);if(g.rule==="one"){const picked=items.filter(i=>itemRank(i)>=1);if(picked.length)open=picked.filter(i=>itemRank(i)<3)}open.forEach(i=>{const bundles=itemBundles(i),chosen=bundles.filter(b=>Math.min(...b.map(rankOf))>=1);(chosen.length?chosen:bundles).forEach(b=>b.forEach(id=>ids.add(id)))})})));return ids}
function renderCourses(){const s=getStats(),order={planning:0,none:1},need=neededCourseIds(),rank=new Map(courseCandidates().map((x,i)=>[x.c.id,i])),courses=activeCourses().filter(c=>Object.hasOwn(order,statusOf(c.id))&&(!need||need.has(c.id))).sort((a,b)=>order[statusOf(a.id)]-order[statusOf(b.id)]||(rank.has(a.id)?rank.get(a.id):999)-(rank.has(b.id)?rank.get(b.id):999));byId("course-content").innerHTML=(courses.length?'<div class="fit-list next-semester-list">'+courses.map(c=>courseMapRowHTML(c,'<div class="fit-course-slot">'+wizardCourseRow(c,collegeShort(c).toUpperCase()+" COURSE","next")+'</div>')).join("")+'</div>':'<div class="empty-state"><h3>Nothing left to plan.</h3><p>Every course your selected agreements still need is completed or registered.</p></div>');
byId("risk-content").innerHTML='<div class="risk-item"><span class="risk-icon">!</span><div><h3>'+(s.planningUnits>12?"Review your planned workload":assistAgreementFor("ucb")&&PLAN.targetIds.has("ucb")?"Protect the linear-algebra decision":"Verify major applicability")+'</h3><p>'+(s.planningUnits>12?"Your planning list exceeds the demo’s 12-unit scenario limit. It may span multiple terms; review timing and workload with a counselor.":assistAgreementFor("ucb")&&PLAN.targetIds.has("ucb")?"For required group B, the Computer Science agreement note accepts Miramar MATH 254 as the linear-algebra course. MATH 255 alone does not satisfy that decision; the other Berkeley options have no articulated Miramar course.":"Most matches are illustrative or unknown. Check the correct major agreement, course-taking year and prerequisites before making enrollment decisions.")+'</p></div><button class="text-button" data-open="sources">Review</button></div>'}
function renderMatrix(){const rows=selectedRecords(),scope=activeAssistAgreement()?"This pathway uses the linked Miramar ASSIST agreements and preserves grouped-course logic.":"ASSIST cells use static Mesa agreement snapshots and show the agreement year.",kindName={verified:"Source-linked",demo:"Illustrative",unknown:"Not verified"};byId("applicability-matrix").innerHTML='<div class="section-heading"><div><h2 class="eyebrow">YOUR COURSES × YOUR DESTINATIONS</h2></div><span class="source-pill">Course relationships—not admission readiness</span></div><div class="matrix-legend"><span class="match-pill verified">Source-linked</span><span class="match-pill demo">Illustrative</span><span class="match-pill unknown">Not listed / not verified</span></div>'+(rows.length?'<div class="fit-list">'+rows.map(c=>{const s=statusOf(c.id),college=(c.college||"").replace(/^San Diego /,"").replace(/ College$/,"");return '<article class="fit-row" aria-label="'+c.code+' mapped to your destinations"><div class="fit-course status-'+s+'"><span class="map-side-label">'+college.toUpperCase()+' COURSE</span><strong>'+c.code+'</strong><span class="fit-title">'+c.title+'</span><small class="school-inline">'+schoolBadge(c.schoolId||"mesa")+college+' · '+c.units+' units</small><span class="fit-status '+s+'">'+STATUS_LABELS[s]+'</span><button class="evidence-link" data-course-detail="'+c.id+'">Course details ↗</button></div><div class="mapping-arrow"><span aria-hidden="true">→</span><small>maps to</small></div>'+destinationBoxesHTML(c)+'</article>'}).join("")+'</div>':'<div class="empty-state"><h3>Your course history starts here.</h3><p>Add a course status below to see its applicability to your selected campuses.</p></div>')+'<p class="field-help">'+scope+' “Not listed” means the course was not found in that reviewed major agreement—not that it cannot transfer. General UC/CSU transferability does not establish major applicability.</p>'}
const SCHEDULE_HOME={miramar:"R",mesa:"M",city:"C"};
function scheduleHTML(c){const s=typeof SDCCD_SCHEDULE==="undefined"?null:SDCCD_SCHEDULE.courses[c.code];if(!s)return '<div class="schedule"><div class="schedule-head"><span>Sections & seats</span><strong class="schedule-open none">Not in schedule snapshot</strong></div></div>';const home=SCHEDULE_HOME[PLAN.college]||"R",cols=SDCCD_SCHEDULE.colleges,order=Object.keys(cols).sort((a,b)=>(b===home)-(a===home)),statusRank={Open:0,Full:1,Closed:2},rows=s.sections.slice().sort((a,b)=>(b[1]===home)-(a[1]===home)||statusRank[a[5]]-statusRank[b[5]]||a[0]-b[0]).slice(0,3),more=s.total-rows.length;return '<div class="schedule"><div class="schedule-head"><span>'+SDCCD_SCHEDULE.term+' sections</span><strong class="schedule-open '+(s.open?'some':'none')+'">'+s.open+' open of '+s.total+'</strong></div><div class="schedule-counts">'+order.map(k=>'<span class="'+(k===home?'home':'')+'">'+cols[k].name+' '+s.byCollege[k]+'</span>').join("")+'</div>'+(s.byCollege[home]?'':'<p class="schedule-gap">Not offered at '+cols[home].name+' this term — sections below are at other SDCCD colleges.</p>')+'<ul class="section-list">'+rows.map(r=>'<li class="section-row"><div class="section-top">'+schoolBadge(cols[r[1]].id)+'<span class="section-college">'+cols[r[1]].name+' · #'+r[0]+'</span><span class="seat-status '+r[5].toLowerCase()+'">'+r[5]+'</span></div><div class="section-time">'+r[3]+'</div><div class="section-meta">'+r[2]+(r[4]?' · '+r[4]:'')+' · '+r[6]+'/'+r[7]+' enrolled · waitlist '+r[8]+'/'+r[9]+'</div></li>').join("")+'</ul>'+(more>0?'<a class="section-more" href="'+SDCCD_SCHEDULE.source+'" target="_blank" rel="noopener noreferrer">'+more+' more in the SDCCD class search ↗</a>':'')+'</div>'}
function renderExplorer(){const q=explorerQuery.toLowerCase(),courses=activeCourses().filter(c=>statusOf(c.id)!=="completed");const list=courses.filter(c=>(explorerCategory==="All"||c.category===explorerCategory)&&(c.code+" "+c.title).toLowerCase().includes(q));byId("explorer-results").innerHTML=list.length?list.map(c=>'<article class="explorer-card"><div class="explorer-top"><span class="source-pill">'+c.category+'</span><span class="explorer-units">'+c.units+' units</span></div><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span>'+c.title+'</span></button><div class="college-label school-inline">'+schoolBadge(c.schoolId||"mesa")+c.college+' · '+c.catalogYear+'</div>'+scheduleHTML(c)+'<div class="explorer-actions"><button class="button outline" data-explore-add="'+c.id+'">'+(statusOf(c.id)==="none"?"Add to planning":STATUS_LABELS[statusOf(c.id)]+" · View")+'</button>'+link(c.source,c.schoolId==="miramar"?"ASSIST source":"Course page")+'</div></article>').join(""):'<div class="empty-state"><h3>No courses match this sample.</h3><button class="button outline" data-action="clear-search">Clear filters</button></div>';byId("result-count").textContent=list.length+" of "+courses.length+" sample courses";document.querySelector(".district-note p").textContent=activeAssistAgreement()?"Showing the "+courses.length+" courses in your selected ASSIST agreements that aren't completed yet. Sections and seats are an SDCCD class search snapshot for "+SDCCD_SCHEDULE.term+" as of "+new Date(SDCCD_SCHEDULE.retrieved+"T12:00:00").toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})+". "+SDCCD_SCHEDULE.note+" Confirm in the official search before you register.":"The official SDCCD search covers City, Mesa and Miramar. This fallback imports Mesa catalog examples; sections shown come from a dated SDCCD class search snapshot, not a live seat feed."}
function render(){if(PLAN.view!=="dashboard")return;const s=getStats(),agreement=activeAssistAgreement();document.querySelector(".student strong").textContent="Your plan";document.querySelector(".student small").textContent=collegeName();byId("home-school-mark").innerHTML=schoolBadge(PLAN.college);document.querySelector(".workspace-profile>p").textContent=PLAN.major;document.querySelector(".subheading").innerHTML=schoolBadge(PLAN.college)+escapeHTML(collegeName())+" · "+escapeHTML(PLAN.major);byId("next-move").innerHTML=nextMoveHTML();document.querySelector(".family-strip>span").innerHTML="<strong>Make the plan reviewable.</strong> Share the reasoning, risks and open questions with a parent or counselor.";renderTargets();renderCourses();renderMatrix();renderExplorer();document.querySelectorAll("[data-scenario]").forEach(b=>{b.classList.toggle("selected",b.dataset.scenario===PLAN.scenario);b.setAttribute("aria-pressed",String(b.dataset.scenario===PLAN.scenario))});byId("live-status").textContent=s.completed+" completed, "+s.registered+" registered, "+s.planning+" planning courses."; }
document.addEventListener("click",async event=>{const b=event.target.closest("button");if(!b)return;if(b.dataset.open==="sources")return showSources();if(b.dataset.target)return showTarget(b.dataset.target);if(b.dataset.courseDetail)return showCourse(b.dataset.courseDetail);if(b.dataset.scenario)return setScenario(b.dataset.scenario);if(b.dataset.exploreAdd){const id=b.dataset.exploreAdd;if(statusOf(id)==="none"){setCourseStatus(id,"planning");notify("Course added to planning")}else showCourse(id);return}const a=b.dataset.action;if(a==="why")return showWhy();if(a==="share"||a==="parent")return showShare(a==="parent");if(a==="edit-profile")return beginEdit(1);if(a==="edit-targets")return beginEdit(2);if(a==="edit-courses")return beginEdit(4);if(a==="clear-search"){explorerQuery="";explorerCategory="All";byId("course-search").value="";byId("category-filter").value="All";return renderExplorer()}if(a==="confirm-reset"){dialog.close();return startOver()}if(a==="copy-summary"||a==="copy-link"){const text=a==="copy-summary"?summary():location.origin+location.pathname;try{await navigator.clipboard.writeText(text);notify(a==="copy-summary"?"Your summary was copied":"Demo link copied—answers are not included")}catch{showDialog("Copy your summary",'<p>Select and copy the text below.</p><textarea id="copy-fallback" readonly aria-label="Summary text"></textarea>');byId("copy-fallback").value=text;byId("copy-fallback").select()}return}if(a==="download-summary"){const url=URL.createObjectURL(new Blob([summary()],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="transfer-copilot-plan.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify("Your planning summary was downloaded")}});
document.addEventListener("change",e=>{if(e.target.dataset.planStatus)setCourseStatus(e.target.dataset.planStatus,e.target.value)});
byId("course-search").addEventListener("input",e=>{explorerQuery=e.target.value;renderExplorer()});
byId("category-filter").addEventListener("change",e=>{explorerCategory=e.target.value;renderExplorer()});
byId("close-dialog").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
byId("reset").textContent="Start over";
byId("reset").addEventListener("click",()=>showDialog("Start a new plan?",'<p>This clears the college, destinations and course statuses in this tab. Download your summary first if you want to keep it.</p><button class="button navy" data-action="confirm-reset">Clear this plan & start over</button>'));
byId("share").addEventListener("click",()=>showShare());
const context=document.modelContext;
document.querySelectorAll('.workspace-header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.workspace-header nav a').forEach(link=>{link.classList.toggle('active',link===a);if(link===a)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}));
if(context?.registerTool){const life=new AbortController();window.addEventListener("pagehide",()=>life.abort(),{once:true});const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}};
register({name:"read_sample_transfer_plan",title:"Read current demo plan",description:"Read current course statuses, campus choices and counts. No name is collected. No official eligibility conclusion.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>readState()});
register({name:"configure_sample_scenario",title:"Configure planning scenario",description:"After onboarding, change only planning courses while preserving completed and registered records. No enrollment or saving.",inputSchema:{type:"object",properties:{scenario:{type:"string",enum:["balanced","lighter","original"]}},required:["scenario"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).some(k=>k!=="scenario"))throw new Error("Invalid input");return setScenario(input.scenario)}});
register({name:"configure_course_status",title:"Set a course status",description:"Update one active sample course to completed, registered, planning, or not added. Self-reported demo only.",inputSchema:{type:"object",properties:{courseId:{type:"string",enum:ALL_COURSES.map(c=>c.id)},status:{type:"string",enum:Object.keys(STATUS_LABELS)}},required:["courseId","status"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(PLAN.view!=="dashboard")throw new Error("Complete setup first");if(!input||Object.keys(input).some(k=>!["courseId","status"].includes(k)))throw new Error("Invalid input");return setCourseStatus(input.courseId,input.status)}});
}
